// One geometry contract for collision, automatic placement and Cocos rendering.
// World/UI coordinates share +Y up. No stored debuff survives leaving the field.
export function sancaiVertices({x = 0, y = 0, radius}) {
  const halfWidth = Math.sqrt(3) * radius / 2
  return [{x, y: y + radius}, {x: x - halfWidth, y: y - radius / 2},
    {x: x + halfWidth, y: y - radius / 2}]
}

export function sancaiContains(zone, target) {
  const vertices = sancaiVertices(zone), radius = Math.max(0, target.radius || 0)
  let inside = true
  for (let i = 0; i < 3; i++) {
    const a = vertices[i], b = vertices[(i + 1) % 3]
    const dx = b.x - a.x, dy = b.y - a.y
    if (dx * (target.y - a.y) - dy * (target.x - a.x) < -1e-9) inside = false
    const t = Math.max(0, Math.min(1,
      ((target.x - a.x) * dx + (target.y - a.y) * dy) / (dx * dx + dy * dy || 1)))
    if (Math.hypot(target.x - a.x - t * dx, target.y - a.y - t * dy) <= radius + 1e-9) return true
  }
  return inside
}

// Targets arrive in the existing visibility/range/priority order. Prefer the
// forward half-plane, then turn if necessary; ties preserve the prior ordering.
export function sancaiTarget(targets, player, radius, visibleFrom = () => true) {
  const forward = targets.filter(e => (e.x - player.x) * player.faceX + (e.y - player.y) * player.faceY >= 0)
  const candidates = forward.length ? forward : targets
  let best = null, count = -1
  for (const target of candidates) {
    const zone = {x: target.x, y: target.y, radius}
    const covered = Math.min(6, targets.filter(e => sancaiContains(zone, e) && visibleFrom(target, e)).length)
    if (covered > count) { best = target; count = covered }
  }
  return best
}
